public void new()
{
    outboundMessageTable.MessageGUID = newGuid();
    outboundMessageTable.SourceDateTime = DateTimeUtil::getSystemDateTime();
    outboundMessageTable.MessageStatus = OMGProcessingStatus::Ready;
    outboundMessageTable.SourceCompany = curext();
}

